INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-001', 'S', 'lrp', 'A', '{"title":"Library volunteer","scenario":"You are a new volunteer at a college library. A librarian is showing you how to help visitors.","sentences":["Please welcome visitors at the front desk.","Show them where the quiet study rooms are.","Visitors with a student card can borrow up to five books.","If a book is late, please ask the visitor to pay a fee.","The printers on the second floor are free for all students.","Anyone looking for old newspapers should ask the basement librarian.","Remind everyone to return their books before the library closes."],"syl":[10,10,15,15,14,18,17]}', NULL, NULL, NULL, -1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-002', 'S', 'lrp', 'A', '{"title":"Campus café trainee","scenario":"You are a new worker at the campus café. The manager is explaining the rules of the job.","sentences":["Always wash your hands before starting work.","Greet every customer with a smile.","Write each order clearly on a card and give it to the cook.","Please keep the counter clean and put the cups back on the shelf.","If a customer has an allergy, ask the manager first.","The coffee machine must be turned off and cleaned at the end of every evening.","On busy days, you can take a short break after you finish the lunch rush."],"syl":[10,11,15,14,16,21,18]}', NULL, NULL, NULL, -1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-003', 'S', 'lrp', 'A', '{"title":"Dormitory helper","scenario":"You are a student helper at a dormitory. A resident advisor is training you to welcome new students.","sentences":["Give each new student a key and a folder.","Show them where the laundry room is located.","Remind them that visitors must leave the building by ten o''clock.","The kitchen on each floor is shared by all of the residents.","If students lose their keys, they should contact the front office right away.","Please tell them that the heating in every room can be controlled with the small dial.","Students who need help with their luggage can ask a volunteer wearing a green badge."],"syl":[11,10,16,15,17,20,20]}', NULL, NULL, NULL, -1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-004', 'S', 'lrp', 'A', '{"title":"Laboratory safety","scenario":"You are assisting in a chemistry laboratory. A teaching assistant is explaining the safety rules.","sentences":["Always wear your safety glasses in the lab.","Tie back your hair before you begin.","Never taste or smell any of the chemicals in the lab.","If something spills, tell your instructor and leave the area.","Put used glass into the special box, not into the trash.","After class, wash your hands and return all equipment to the correct shelf.","Students who have long sleeves should roll them up so they do not touch the burners."],"syl":[11,9,14,15,14,18,18]}', NULL, NULL, NULL, -1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-005', 'S', 'lrp', 'B', '{"title":"Science museum guide","scenario":"You are a volunteer guide at a college science museum. A coordinator is training you to talk to visitors.","sentences":["Welcome the visitors to the museum.","Explain how to use the exhibits.","The dinosaur exhibit is located on the second floor.","Young children must always be accompanied by an adult.","Please ask visitors not to touch the fragile glass cases.","The gift shop near the exit sells books, posters, and small science kits for children.","If you cannot answer a question, politely suggest asking a staff member."],"syl":[10,9,15,15,14,18,21]}', NULL, NULL, NULL, 0, 'pretest', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-006', 'S', 'lrp', 'B', '{"title":"International student ambassador","scenario":"You are a student ambassador at the international office. A staff member is training you to give advice to new students.","sentences":["Check your university email daily.","Bring your passport and visa to the office.","The campus bank offers special accounts for new students.","Students can join a conversation group to practice speaking English.","If you have questions about classes, visit your advisor.","You must register for all of your courses online before the first week ends.","Many students visit the writing center, where tutors review their essays."],"syl":[11,11,14,17,14,18,19]}', NULL, NULL, NULL, 0, 'pretest', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-007', 'S', 'lrp', 'B', '{"title":"Psychology survey assistant","scenario":"You are a student assistant in a psychology department. A professor is explaining how to run a short survey.","sentences":["Please greet each participant politely.","Explain that the survey is voluntary.","Participants should sign a consent form before the survey begins.","The questionnaire takes about fifteen minutes to complete.","If someone feels uncomfortable, they may stop at any time.","After each session, thank the participant and write the date in the notebook.","Please keep all the finished answer sheets in the locked cabinet every evening."],"syl":[11,11,17,14,15,20,21]}', NULL, NULL, NULL, 0, 'pretest', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-008', 'S', 'lrp', 'B', '{"title":"Campus tour guide","scenario":"You are leading a campus tour for prospective students. A tour manager is reviewing what to say at each stop.","sentences":["Begin by introducing yourself.","The library is open until midnight.","The science building has modern laboratories for students.","Most first-year students live in the residence halls near the sports center.","Lunch is served in the dining hall from eleven thirty until two.","Students can join one of over a hundred clubs that meet in the union.","Questions about applying can be sent to the admissions office directly."],"syl":[9,11,15,17,17,17,19]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-009', 'S', 'lrp', 'C', '{"title":"Conference volunteer","scenario":"You are volunteering at an academic conference. The organizer is explaining your responsibilities.","sentences":["Please check each guest''s name badge carefully.","Direct guests to the registration desk.","Speakers must arrive early to test their presentation equipment.","Lunch is provided for registered participants only.","The poster session takes place in the east wing of the building.","Anyone having difficulty hearing should be directed to the front seats.","If a technical problem occurs, tell the coordinator right away."],"syl":[10,10,17,14,15,18,18]}', NULL, NULL, NULL, 1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-010', 'S', 'lrp', 'C', '{"title":"Student newspaper intern","scenario":"You are an intern at the student newspaper. An editor is explaining how to prepare for an interview.","sentences":["Research your subject thoroughly beforehand.","Prepare questions that need detailed answers.","Always ask permission before recording a conversation.","Listen closely, since good questions often follow answers.","Take notes by hand as well, in case the recording does not work.","Afterward, send a brief message to thank the person and confirm the quotations.","Every claim in an article should be supported by a reliable source."],"syl":[12,10,16,15,15,20,19]}', NULL, NULL, NULL, 1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-011', 'S', 'lrp', 'C', '{"title":"Water-testing project","scenario":"You are a research assistant in an environmental science laboratory. A professor is describing a water-testing project.","sentences":["We collect samples from the river weekly.","Label each bottle with the date and place.","The samples must be kept cold until they reach the laboratory.","Measure the temperature and acidity of the water first.","Record each measurement carefully in your field notebook.","Because the instruments are sensitive, carry them in the protective case.","If the readings differ greatly from last week''s results, repeat the test again."],"syl":[11,10,17,17,17,19,19]}', NULL, NULL, NULL, 1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-012', 'S', 'lrp', 'C', '{"title":"Teaching assistant duties","scenario":"You are a teaching assistant for an introductory economics course. The instructor is explaining your duties.","sentences":["Please arrive ten minutes before class.","Hand out the problem sets at the door.","Students often ask what the final exam will cover.","Direct those questions to me instead of answering them yourself.","Weekly tutorials are held on Tuesday and Thursday afternoons.","Please explain to students that late assignments lose ten percent for each day.","At the end of the semester, you will help organize the final projects."],"syl":[9,9,14,16,16,18,19]}', NULL, NULL, NULL, 1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-013', 'S', 'lrp', 'B', '{"title":"Recycling center","scenario":"You are helping at the campus recycling center. The supervisor is explaining how to sort items for incoming students.","sentences":["Please sort the plastic bottles by color.","Paper goes into the blue containers.","Cardboard boxes should be flattened before they go in the bin.","Glass containers need to be rinsed and placed on the top shelf.","If you are unsure about an item, ask the supervisor.","Batteries and other electronic devices should go to the front desk.","Before you leave, please make sure each container is empty and the lid is closed."],"syl":[10,10,14,14,16,18,19]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-014', 'S', 'lrp', 'B', '{"title":"IT help desk","scenario":"You have a part-time job at the campus IT help desk. A supervisor is training you to assist students with common problems.","sentences":["Greet each student and ask for a name.","Check whether the printer has paper.","Most wireless problems can be fixed by restarting the router.","Students who forget their passwords must show a valid student card.","If a laptop will not turn on, plug it in for ten minutes first.","Please tell students that the library lends tablets and chargers for up to three days.","At closing time, record every repair in the log and lock the cabinet."],"syl":[9,9,16,16,16,20,20]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-015', 'S', 'lrp', 'B', '{"title":"Career fair volunteer","scenario":"You are volunteering at a university career fair. A coordinator is explaining how to welcome employers and students.","sentences":["Welcome each employer at the entrance.","Give every visitor a name tag.","Employers are seated at tables arranged by industry.","Please direct students to the resume workshop in the small hall.","If a representative needs water, bring it to their table.","Students should bring several copies of their resumes and a list of questions.","When the fair closes, help the employers pack up their displays carefully."],"syl":[10,10,14,15,16,19,18]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-016', 'S', 'lrp', 'B', '{"title":"Fitness center desk","scenario":"You are working at the front desk of the campus fitness center. The manager is describing your responsibilities.","sentences":["Scan each student''s card at the door.","Towels are available near the lockers.","Group classes fill up quickly, so students should reserve a spot online.","Visitors must pay a small fee unless a member brings them.","Please remind everyone to wipe the machines after using them.","If you notice any damaged equipment, put a sign on it and tell me.","The pool closes for cleaning every Wednesday, so please empty your locker by noon."],"syl":[8,11,16,15,16,18,21]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-017', 'S', 'lrp', 'B', '{"title":"Campus radio station","scenario":"You are a new volunteer at the campus radio station. A student manager is showing you how the studio works.","sentences":["Turn on the microphone before you speak.","Keep your headphones on during the show.","Each program begins with a short introduction and the news.","Please choose music that is appropriate for all listeners.","If a guest arrives early, offer them a seat in the lounge.","Never open the studio door while the red light above it is shining.","After your show, save the recording and write the song list on the schedule board."],"syl":[10,9,15,14,15,19,20]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-018', 'S', 'lrp', 'B', '{"title":"Campus bookstore","scenario":"You are working at the campus bookstore at the start of the semester. The manager is explaining how to help customers.","sentences":["Ask students which courses they are taking.","Used books are cheaper than new ones.","Textbooks can be returned within two weeks with a receipt.","Please restock the popular titles every morning.","Students can sell their old books back at the counter near the entrance.","Customers who want a discount should show a student card before they pay.","If a book is out of stock, take the customer''s email so the store can order it."],"syl":[9,8,14,14,16,18,21]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-019', 'S', 'lrp', 'B', '{"title":"Community garden","scenario":"You are volunteering at a community garden run by the university. The garden leader is explaining the weekly tasks.","sentences":["Water the plants early in the morning.","Pull out the weeds around the tomatoes.","Vegetables are picked on Fridays and shared with families.","Please wear gloves and a hat when you work outside in the sun.","Please return all of the tools to the shed before you leave.","New volunteers should ask a leader before they plant anything in the empty beds.","During the summer, the garden hosts workshops where neighbors learn how to grow their own food."],"syl":[10,10,15,14,14,21,21]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-020', 'S', 'lrp', 'B', '{"title":"Admissions office intern","scenario":"You are an intern in the university admissions office. A staff member is explaining how to answer questions from applicants.","sentences":["Greet visitors with a friendly smile.","Applications are due by the first of March.","Please explain that all documents must be sent together.","Applicants can check their status on the university website.","If someone asks about scholarships, give them the information sheet.","International applicants must also submit proof of their English test scores.","Students who want to visit the campus can sign up for a guided tour at the front desk."],"syl":[10,11,14,17,17,20,21]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-001', 'S', 'int', 'A', '{"title":"Study habits","scenario":"A university is doing a survey about how students study. You will answer four questions from a researcher.","questions":["Where do you usually study, and why do you prefer that place?","What kinds of things distract you when you try to study?","Some people think students learn better in groups. What do you think?","How do you think studying will change in the next ten years?"]}', NULL, NULL, NULL, -1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-002', 'S', 'int', 'A', '{"title":"Free time","scenario":"A student magazine is asking readers about free time. You will answer four questions from a reporter.","questions":["What do you usually do on your days off?","Tell me about a hobby that you started recently or would like to start.","Do you think young people today have enough free time? Why or why not?","If you suddenly had a free month, how would you spend it?"]}', NULL, NULL, NULL, -1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-003', 'S', 'int', 'A', '{"title":"Food on campus","scenario":"A university is asking students about the food on campus. You will answer four questions from a researcher.","questions":["What do you usually eat for lunch on a school day?","How do you decide where to eat when you have a short break?","Some universities want to offer only healthy food. Do you think that is a good idea?","How might food on campuses change in the future?"]}', NULL, NULL, NULL, -1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-004', 'S', 'int', 'A', '{"title":"Getting around the city","scenario":"A city office is studying how people travel. You will answer four questions from a researcher.","questions":["How do you usually travel to school or work?","Tell me about a time when your trip took longer than you expected.","Many cities want people to use bicycles more. What do you think about this?","If your city could change one thing about its transportation, what should it be?"]}', NULL, NULL, NULL, -1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-005', 'S', 'int', 'A', '{"title":"Friends and communication","scenario":"A university research group is studying how young people stay in touch. You will answer four questions from a researcher.","questions":["How do you usually keep in touch with your friends?","Do you prefer to send messages or to talk on the phone? Why?","Some people say that technology makes friendships weaker. What is your opinion?","How do you think people will communicate with each other in twenty years?"]}', NULL, NULL, NULL, -1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-006', 'S', 'int', 'B', '{"title":"Learning languages","scenario":"A university is doing a study on language learning. You will answer four questions from a researcher.","questions":["Tell me about a language you have studied and how you began learning it.","What is the most helpful method you have found for improving your speaking?","Some people believe that apps will soon replace language teachers. Do you agree?","Imagine that everyone in the world spoke one common language. What would be the advantages and disadvantages?"]}', NULL, NULL, NULL, 0, 'pretest', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-007', 'S', 'int', 'B', '{"title":"Work and study","scenario":"A scholarship committee is interviewing students about working while studying. You will answer four questions.","questions":["Have you ever had a job or volunteer position while you were studying? Please describe it.","What skills do you think students can learn from working that they cannot learn in class?","Some universities limit how many hours students can work. Do you think this is a good rule?","If you were advising a first-year student, would you recommend working during the first semester? Why?"]}', NULL, NULL, NULL, 0, 'pretest', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-008', 'S', 'int', 'B', '{"title":"Choosing a major","scenario":"The career center is collecting students'' views on choosing a field of study. You will answer four questions from an adviser.","questions":["How did you decide what to study, or how do you plan to decide?","What do you think is the most important thing to consider when choosing a career?","Many people change their major at least once. Is that a positive or negative thing, in your view?","How might the jobs available to graduates be different in the future?"]}', NULL, NULL, NULL, 0, 'pretest', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-009', 'S', 'int', 'B', '{"title":"Sleep and schedules","scenario":"A university health project is studying student schedules. You will answer four questions from a researcher.","questions":["Describe your typical daily schedule during a busy week.","What do you do to stay focused when you are tired?","Some schools are moving the start of the day later to give students more sleep. What do you think of this idea?","If you could design the perfect schedule for students, what would it include?"]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-010', 'S', 'int', 'B', '{"title":"Public spaces","scenario":"A planning department is asking residents about public spaces in the city. You will answer four questions from a researcher.","questions":["Tell me about a public place in your city that you enjoy visiting.","What makes a public space comfortable for people to spend time in?","Some cities are replacing parking areas with parks. Do you think this is a good idea?","How do you think public spaces will change as more people work from home?"]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-011', 'S', 'int', 'C', '{"title":"Social media","scenario":"A university is researching the effects of social media. You will answer four questions from a researcher.","questions":["Which social media platforms do you use most, and how do you use them?","In what ways has social media changed the way you get information?","Some researchers say social media reduces people''s attention span. To what extent do you agree?","If governments were to regulate social media more strictly, what effects might this have?"]}', NULL, NULL, NULL, 1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-012', 'S', 'int', 'C', '{"title":"Environmental habits","scenario":"An environmental group is interviewing students about daily habits. You will answer four questions from an interviewer.","questions":["What have you done in your daily life to reduce waste?","What do you think prevents people from adopting more environmentally friendly habits?","Some people argue that individual actions matter little compared with the actions of companies. What is your view?","Suppose your city offered rewards for people who reduce their waste. How effective do you think this would be?"]}', NULL, NULL, NULL, 1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-013', 'S', 'int', 'C', '{"title":"Decision-making","scenario":"A psychology department is studying how people make decisions. You will answer four questions from a researcher.","questions":["Tell me about an important decision you made recently.","When you have to make a difficult decision, do you prefer to rely on advice or on your own judgment? Why?","Some people claim that having too many choices makes decisions harder. Do you agree?","How might artificial intelligence change the way people make important decisions?"]}', NULL, NULL, NULL, 1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-014', 'S', 'int', 'C', '{"title":"Traditions and change","scenario":"A cultural studies project is collecting students'' views on traditions. You will answer four questions from a researcher.","questions":["Describe a tradition in your family or community that is important to you.","Why do you think some traditions survive for generations while others disappear?","Is it more valuable to preserve traditions or to adapt them to modern life? Explain.","How do you imagine your community will celebrate this tradition fifty years from now?"]}', NULL, NULL, NULL, 1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-015', 'S', 'int', 'C', '{"title":"Learning outside the classroom","scenario":"A university committee is studying education reform. You will answer four questions from a committee member.","questions":["Tell me about something important that you learned outside of school.","What are the benefits of learning from experience compared with learning from teachers?","Some employers value practical experience more than university degrees. What is your opinion?","If universities were redesigned from the beginning, what changes would you suggest?"]}', NULL, NULL, NULL, 1, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-016', 'S', 'int', 'B', '{"title":"Volunteering","scenario":"A university service office is studying student volunteering. You will answer four questions from a coordinator.","questions":["Have you ever done volunteer work? Please describe what you did.","What kinds of volunteer activities do you think are most enjoyable for students?","Some schools require students to complete volunteer hours before they graduate. What do you think of this rule?","How might volunteering change in the future as more people work and study online?"]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-017', 'S', 'int', 'B', '{"title":"Exercise and health","scenario":"A campus health program is collecting information about student fitness. You will answer four questions from a researcher.","questions":["How often do you exercise, and what kind of activity do you usually do?","What makes it easy or difficult for you to stay active during a busy week?","Some universities offer free gym memberships to all students. Do you think this is a good use of money?","If you were designing a program to help students become healthier, what would you include?"]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-018', 'S', 'int', 'B', '{"title":"Travel experiences","scenario":"A tourism research group is asking students about travel. You will answer four questions from an interviewer.","questions":["Tell me about a trip that you remember well.","Do you prefer to travel with friends, with family, or alone? Why?","Some people say that tourism harms the places that people visit. What is your opinion?","How do you think traveling will be different for the next generation?"]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-019', 'S', 'int', 'B', '{"title":"Reading habits","scenario":"A library committee is studying how students read. You will answer four questions from a researcher.","questions":["What kinds of things do you read in your free time?","Do you prefer reading on paper or on a screen, and why?","Some people believe young people read less than they used to. Do you agree?","What changes might happen to books and libraries over the next twenty years?"]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-020', 'S', 'int', 'B', '{"title":"Technology in class","scenario":"A university teaching center is studying technology in classrooms. You will answer four questions from an adviser.","questions":["Which technology do you use most when you study for class?","How does technology help you learn, and when does it make learning harder?","Some teachers ban phones and laptops in their classrooms. Do you think this is a good policy?","If you could add one new technology to every classroom, what would it be and why?"]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-021', 'S', 'int', 'B', '{"title":"Managing money","scenario":"A student services office is surveying students about personal finances. You will answer four questions from a counselor.","questions":["How do you usually decide what to spend your money on?","What do you do when you want to buy something but do not have enough money?","Some people think universities should teach every student how to manage money. What is your view?","How do you think the way people pay for things will change in the future?"]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-022', 'S', 'int', 'B', '{"title":"Housing choices","scenario":"A city housing office is asking students about where they live. You will answer four questions from a researcher.","questions":["Tell me about the place where you live now and what you like about it.","What is the most important thing to consider when choosing a place to live?","Some students prefer living with roommates, while others prefer living alone. Which do you think is better?","If you could design the ideal student neighborhood, what would it include?"]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-023', 'S', 'int', 'B', '{"title":"Art and creativity","scenario":"A university is conducting a study on art and creativity. You will answer four questions from a researcher.","questions":["Describe a creative activity that you enjoy or have tried.","How do you feel when you visit a museum or an art exhibition?","Some people say schools should spend more time on art and music. Do you agree or disagree?","How might technology change the way that artists create their work?"]}', NULL, NULL, NULL, 0, 'active', 1793561454926, 1793561454926)
